WITH StoreStats AS (SELECT store_id, ROUND((100 * SUM(CASE WHEN status = 'SHIPPED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_shipped, COUNT(CASE WHEN status = 'PENDING' THEN 1 END) AS pending_count FROM orders WHERE status IN ('CANCELLED', 'SHIPPED') GROUP BY store_id) SELECT s.city, s.sqft, S.pct_shipped, S.pending_count FROM stores s LEFT JOIN StoreStats S ON s.id = S.store_id WHERE S.pct_shipped >= 35 ORDER BY S.pending_count DESC;
